// AllianzGI OMS extracts. Only the AllianzGI agent may import this module.
// Schemas follow data/DATA_DICTIONARY.md; /data is regenerated by script, never edited by hand.
import "server-only";
import { z } from "zod";
import { AGI_ORDER, ISIN, LEI, agiTs, id, int, loadTables, nullable, num, text } from "./core";

const FUND = /^AGI-[A-Z]{4}$/;

export const orderSchema = z.object({
  agi_order_id: id(AGI_ORDER),
  created_ts_cet: agiTs(),
  portfolio_manager: text(),
  fund_code: id(FUND),
  side: z.enum(["BUY", "SELL"]),
  isin: id(ISIN),
  quantity: num(),
  limit_price: num(),
  broker: text(),
  status: z.enum(["FILLED"]),
});

export const allocationSchema = z.object({
  allocation_id: id(/^ALC-\d{2}-\d{3}-\d{4}-\d+$/),
  agi_order_id: id(AGI_ORDER),
  fund_code: id(FUND),
  quantity: num(),
  version: int(),
  amended_ts_cet: nullable(agiTs()),
  custodian: text(),
  sent_to_custodian_ts_cet: agiTs(),
  status: z.enum(["SENT", "SUPERSEDED"]),
});

export const fundSchema = z.object({
  fund_code: id(FUND),
  fund_name: text(),
  domicile: z.enum(["LU", "DE", "UK"]),
  custodian: text(),
  base_currency: z.enum(["USD", "EUR"]),
});

export const brokerSchema = z.object({
  broker_name: text(),
  broker_lei: id(LEI),
  approved_markets: text(),
  status: z.enum(["APPROVED"]),
});

const schemas = {
  orders: orderSchema,
  allocations: allocationSchema,
  funds: fundSchema,
  broker_list: brokerSchema,
};

export type AgiOrder = z.output<typeof orderSchema>;
export type AgiAllocation = z.output<typeof allocationSchema>;
export type AgiFund = z.output<typeof fundSchema>;
export type AgiBroker = z.output<typeof brokerSchema>;
export type AllianzGIData = ReturnType<typeof loadAllianzGI>;

let cache: ReturnType<typeof load> | undefined;
const load = () => loadTables("allianzgi", schemas);

/** All AllianzGI tables, parsed once and cached in memory. */
export function loadAllianzGI() {
  return (cache ??= load());
}
